#### P1379 八数码难题
https://www.luogu.com.cn/problem/P1379#ide
```cpp
constexpr int dirX[4] = { 1, -1, 0, 0 };
constexpr int dirY[4] = { 0, 0, 1, -1 };

struct Board {
	int grid[5][5];

	bool operator<(const Board& other) const {
		for(int i = 1; i <= 3; i++)
			for(int j = 1; j <= 3; j++)
				if(grid[i][j] != other.grid[i][j])
					return grid[i][j] < other.grid[i][j];
		return false;
	}
};

// 目标状态（固定）
Board targetBoard;
// 当前搜索状态
Board currentBoard;

// 启发式函数 h(n)：计算错位数（除了0以外的数字）
// 这是一个可采纳的启发式（低估实际代价），保证A*最优性，高估会导致找到的可能不是最优
int getHeuristic(const Board& board) {
	int misplacedCount = 0;
	for(int i = 1; i <= 3; i++) {
		for(int j = 1; j <= 3; j++) {
			// 统计位置不对且不是空格(0)的棋子数量
			if(board.grid[i][j] != targetBoard.grid[i][j] && board.grid[i][j] != 0) {
				misplacedCount++;
			}
		}
	}
	return misplacedCount;
}

// 搜索队列中的节点
struct SearchNode {
	Board board;  // 当前的棋盘状态
	int	  steps;  // 从起点到这里的步数 g(n)

	// 优先队列的比较函数：按 f(n) = steps + 启发值 从小到大排序
	// 注意：这里反过来写是因为 priority_queue 默认是大顶堆
	bool operator<(const SearchNode& other) const {
		// f(n) = g(n) + h(n)
		int currentF = steps + getHeuristic(board);
		int otherF	 = other.steps + getHeuristic(other.board);
		return currentF > otherF;  // 小顶堆：f值小的优先
	}
};

priority_queue<SearchNode> searchQueue;	 // A* 优先队列
set<Board> visitedBoards;

int main() {
	// 1 2 3
	// 8 0 4
	// 7 6 5
	targetBoard.grid[1][1] = 1;
	targetBoard.grid[1][2] = 2;
	targetBoard.grid[1][3] = 3;
	targetBoard.grid[2][1] = 8;
	targetBoard.grid[2][2] = 0;
	targetBoard.grid[2][3] = 4;
	targetBoard.grid[3][1] = 7;
	targetBoard.grid[3][2] = 6;
	targetBoard.grid[3][3] = 5;

	Board startBoard;
	for(int i = 1; i <= 3; i++) {
		for(int j = 1; j <= 3; j++) {
			char ch;
			cin >> ch;
			startBoard.grid[i][j] = ch - '0';
		}
	}

	// A* 搜索
	visitedBoards.insert(startBoard);
	searchQueue.push({ startBoard, 0 });

	while(!searchQueue.empty()) {
		SearchNode currentNode = searchQueue.top();
		searchQueue.pop();

		// 检查是否到达目标状态
		if(getHeuristic(currentNode.board) == 0) {
			cout << currentNode.steps << endl;
			return 0;
		}

		// 找到空格(0)的位置
		int emptyRow, emptyCol;
		for(int i = 1; i <= 3; i++) {
			for(int j = 1; j <= 3; j++) {
				if(currentNode.board.grid[i][j] == 0) {
					emptyRow = i;
					emptyCol = j;
				}
			}
		}
		for(int dir = 0; dir < 4; dir++) {
			int newRow = emptyRow + dirX[dir];
			int newCol = emptyCol + dirY[dir];
			if(newRow >= 1 && newRow <= 3 && newCol >= 1 && newCol <= 3) {
				// 生成新状态：移动棋子到空格
				Board newBoard = currentNode.board;
				swap(newBoard.grid[emptyRow][emptyCol], newBoard.grid[newRow][newCol]);

				// 去重：如果这个状态没访问过，加入队列（防止反复走同样的步）
				if(!visitedBoards.count(newBoard)) {
					visitedBoards.insert(newBoard);
					searchQueue.push({ newBoard, currentNode.steps + 1 });
				}
			}
		}
	}
	return 0;
}
```

>[!question] 为什么使用 set 作为 visited 数组？
>vistedBoard 目的是记录已访问状态，避免重复，使用 unordered_set 也行，不过要定义 hash 函数，这里 board 的 operator<重载已经定义了去重和哈希（小于可以推导出不同，set 的本质平衡二叉树也只需要这一个运算关系），而 board 重载 `!=` 或 `==` 可以满足去重，但是底层由哈希表构建，所以需要定义哈希函数

